INSERT INTO public.memories (category, title, content, metadata) VALUES ('Local AI & GGUF Engineering', 'Local 0.5B LLM Weight Quantization: Engineering Protocols for Bakelite using V-Bit 60-Degree Engraver', '### Executive Summary & Technical Scope

