INSERT INTO public.memories (category, title, content, metadata) VALUES ('Spindle Mechanics', 'G-Code Lookahead Buffer Tuning: Engineering Protocols for Delrin POM using Ballnose 4mm 3D Sculptor', '### Executive Summary & Technical Scope

