INSERT INTO public.memories (category, title, content, metadata) VALUES ('CAD/CAM Algorithms', 'VFD Inverter Harmonics & Shielding: Engineering Protocols for High-Density MDF using 12mm Roughing Hogger', '### Executive Summary & Technical Scope

