INSERT INTO public.memories (category, title, content, metadata) VALUES ('Materials Science', 'Titanium Diboride (TiB2) Endmill Coatings: Engineering Protocols for Bakelite using 6mm 2-Flute Carbide Upcut', '### Executive Summary & Technical Scope

