INSERT INTO public.memories (category, title, content, metadata) VALUES ('Spindle Mechanics', 'G-Code Lookahead Buffer Tuning: Engineering Protocols for 6061-T6 Aluminum using Ballnose 4mm 3D Sculptor', '### Executive Summary & Technical Scope

